contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint _val) public {
        require(true);

        bool firstReverted;
        c.SetMinSum(_val); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            firstReverted = true;
        } else {
            firstReverted = false;
        }

        uint minSumAfter = c.MinSum(); if (__ESBMC_reverted()) return;

        bool secondReverted;
        c.Initialized(); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            secondReverted = true;
        } else {
            secondReverted = false;
        }

        assert(!firstReverted && minSumAfter == _val && !secondReverted);
    }
}

